import React, { useState, useEffect, useRef } from 'react';
import { useLocation, useNavigate } from 'react-router-dom';
import socket from '../../socket';
import './PlayerDashboard.css';

const statConfig = {
    Strength: ['Saving Throw', 'Athletics'],
    Dexterity: ['Saving Throw', 'Acrobatics', 'Sleight of Hand', 'Stealth'],
    Constitution: ['Saving Throw'],
    Intelligence: ['Saving Throw', 'Arcana', 'History', 'Investigation', 'Nature', 'Religion'],
    Wisdom: ['Saving Throw', 'Animal Handling', 'Insight', 'Medicine', 'Perception', 'Survival'],
    Charisma: ['Saving Throw', 'Deception', 'Intimidation', 'Performance', 'Persuasion']
};

const calculateModifier = (score) => Math.floor((score - 10) / 2);

const PlayerDashboard = () => {
    const location = useLocation();
    const navigate = useNavigate();
    const logContainerRef = useRef(null);

    // --- PANEL STATE'LERİ ---
    const [isTopOpen, setIsTopOpen] = useState(true);
    const [isLeftOpen, setIsLeftOpen] = useState(true);
    const [isRightOpen, setIsRightOpen] = useState(true);

    // --- KARAKTER & OYUN STATE'LERİ ---
    const [character, setCharacter] = useState(location.state?.character || null);
    const [gameCode, setGameCode] = useState(location.state?.gameCode || 'UNKNOWN');
    const [logs, setLogs] = useState([{ id: 1, text: '🎲 Oturuma bağlandınız. GM bekleniyor...', type: 'info' }]);
    const [selectedStat, setSelectedStat] = useState('Dexterity');
    const [isConnected, setIsConnected] = useState(false);

    // --- HARITA STATE'İ (GM'den gelecek) ---
    const [activeMapUrl, setActiveMapUrl] = useState(null);
    const [tokens, setTokens] = useState([]);
    const [combatState, setCombatState] = useState({ isActive: false, round: 1, currentTurnIndex: 0 });

    // --- REDIRECT GUARD ---
    useEffect(() => {
        if (!character) {
            navigate('/join-game');
            return;
        }

        // Socket bağlantısını başlat ve odaya katıl
        socket.connect();
        socket.emit('join_room', {
            gameCode,
            playerName: character.name
        });

        setIsConnected(true);
        addLog(`✅ ${gameCode} odasına bağlanıldı!`, 'success');

        // --- SOCKET OLAYLARINI DİNLE ---
        socket.on('log_update', ({ text, type }) => {
            addLog(text, type || 'info');
        });

        socket.on('player_joined', ({ playerName }) => {
            addLog(`👤 ${playerName} oturuma katıldı.`, 'info');
        });

        socket.on('player_left', ({ playerName }) => {
            addLog(`👤 ${playerName} oturumdan ayrıldı.`, 'info');
        });

        socket.on('map_changed', ({ mapUrl }) => {
            setActiveMapUrl(mapUrl);
            addLog('🗺️ GM yeni bir harita açtı.', 'info');
        });

        socket.on('tokens_updated', ({ tokens: newTokens }) => {
            setTokens(newTokens);
        });

        socket.on('combat_updated', ({ combatState: cs, tokens: newTokens }) => {
            setCombatState(cs);
            setTokens(newTokens);
            if (cs.isActive) {
                addLog('⚔️ Savaş başladı!', 'combat');
            } else {
                addLog('🛡️ Savaş sona erdi.', 'info');
            }
        });

        socket.on('hp_changed', ({ playerId, currentHp }) => {
            // TODO: playerId ile eşleşme (backend auth entegre edilince)
            addLog(`💔 HP güncellendi: ${currentHp}`, 'damage');
        });

        // Cleanup: bileşen unmount olduğunda odadan çık ve socket'i kes
        return () => {
            socket.emit('leave_room', { gameCode, playerName: character.name });
            socket.off('log_update');
            socket.off('player_joined');
            socket.off('player_left');
            socket.off('map_changed');
            socket.off('tokens_updated');
            socket.off('combat_updated');
            socket.off('hp_changed');
            socket.disconnect();
        };
    // eslint-disable-next-line react-hooks/exhaustive-deps
    }, []);

    // Log container otomatik scroll
    useEffect(() => {
        if (isRightOpen && logContainerRef.current) {
            logContainerRef.current.scrollTop = logContainerRef.current.scrollHeight;
        }
    }, [logs, isRightOpen]);

    if (!character) return null;

    const profBonus = Math.ceil(character.level / 4) + 1;

    const handleStatChange = (field, value) => {
        setCharacter(prev => ({ ...prev, [field]: value }));
    };

    const toggleInspiration = () => {
        setCharacter(prev => ({ ...prev, inspiration: !prev.inspiration }));
    };

    const addLog = (text, type = 'info') => {
        setLogs(prev => [...prev, { id: Date.now() + Math.random(), text, type }]);
    };

    const rollDice = (name, bonus) => {
        const roll = Math.floor(Math.random() * 20) + 1;
        const total = roll + bonus;
        const rollText = `🎲 ${character.name} – ${name}: 1d20(${roll}) ${bonus >= 0 ? '+' : ''}${bonus} = ${total}`;
        addLog(rollText, 'dice');
        // Socket üzerinden odaya yayınla
        socket.emit('dice_roll', {
            gameCode,
            playerName: character.name,
            rollText,
            isHidden: false
        });
        if (!isRightOpen) setIsRightOpen(true);
    };

    const getSkillBonusValue = (statName, skillName) => {
        const modifier = calculateModifier(character.stats[statName]);
        const isProficient = character.proficiencies && character.proficiencies[`${statName}-${skillName}`];
        return modifier + (isProficient ? profBonus : 0);
    };

    const getLogClass = (type) => {
        switch(type) {
            case 'dice': return 'log-dice';
            case 'success': return 'log-success';
            case 'combat': return 'log-combat';
            case 'damage': return 'log-damage';
            case 'hidden': return 'log-hidden';
            default: return '';
        }
    };

    // Savaşta bu oyuncunun sırası mı?
    const myToken = tokens.find(t => t.playerId === character.id);
    const myTurnIndex = tokens.findIndex(t => t.playerId === character.id);
    const isMyTurn = combatState.isActive && combatState.currentTurnIndex === myTurnIndex && myTurnIndex !== -1;

    return (
        <div className="player-dashboard-wrapper">

            {/* ================= MY TURN UYARISI ================= */}
            {isMyTurn && (
                <div className="my-turn-alert fade-in">
                    ⚔️ SENİN SIRAN!
                </div>
            )}

            {/* ================= BAĞLANTI DURUMU ================= */}
            <div className={`connection-badge ${isConnected ? 'connected' : 'disconnected'}`}>
                {isConnected ? '● ONLINE' : '● OFFLINE'}
            </div>

            {/* ================= LAYER 0: MAP / BOARD ================= */}
            <div className="layer-map">
                {activeMapUrl ? (
                    <img src={activeMapUrl} alt="Game Map" className="game-map-img" />
                ) : (
                    <div className="board-placeholder">
                        <div className="board-icon">🗺️</div>
                        <h3>GAME BOARD</h3>
                        <p>GM harita paylaşmayı bekliyor...</p>
                    </div>
                )}
                {/* Haritadaki Token'lar */}
                {tokens.map((token, idx) => (
                    <div
                        key={token.id}
                        className={`map-token color-${token.color} ${combatState.isActive && combatState.currentTurnIndex === idx ? 'active-turn-token' : ''}`}
                        style={{ left: token.x, top: token.y, width: 50, height: 50, pointerEvents: 'none' }}
                    >
                        {token.name && <span className="token-name-tag">{token.name}</span>}
                        {token.maxHp && (
                            <div className="token-hp-bar">
                                <div className="token-hp-fill" style={{ width: `${Math.min(100, (token.hp / token.maxHp) * 100)}%` }} />
                            </div>
                        )}
                    </div>
                ))}
            </div>

            {/* ================= LAYER: ÜST MENÜ ================= */}
            <div className={`layer-top-menu ${isTopOpen ? 'open' : 'closed'}`}>
                <div className="top-menu-content">
                    <div className="top-left">
                        <button type="button" className="exit-btn" onClick={() => navigate('/main-menu')}>🚪 ÇIKIŞ</button>

                        <div className="pd-char-info">
                            <span className="pd-char-name">{character.name}</span>
                            <span className="pd-char-sub">Lvl {character.level} {character.charClass} • {character.species}</span>
                        </div>

                        <div className="pd-combat-stats">
                            <div className="pd-stat-box">
                                <label>AC</label>
                                <input type="number" value={character.armorClass} onChange={(e) => handleStatChange('armorClass', parseInt(e.target.value) || 0)} />
                            </div>
                            <div className="pd-stat-box">
                                <label>HIZ</label>
                                <input type="number" value={character.speed} onChange={(e) => handleStatChange('speed', parseInt(e.target.value) || 0)} />
                            </div>
                            <div className="pd-stat-box hp-box">
                                <label>HP</label>
                                <div className="hp-inputs">
                                    <input type="number" value={character.currentHp} onChange={(e) => handleStatChange('currentHp', parseInt(e.target.value) || 0)} className="current-hp" />
                                    <span>/</span>
                                    <input type="number" value={character.maxHp} onChange={(e) => handleStatChange('maxHp', parseInt(e.target.value) || 0)} className="max-hp" />
                                </div>
                            </div>
                            <div className="pd-stat-box">
                                <label>PB</label>
                                <div className="prof-bonus-display">+{profBonus}</div>
                            </div>
                            <button
                                className={`pd-inspiration-btn ${character.inspiration ? 'active' : ''}`}
                                onClick={toggleInspiration}
                                title="İlham Değiştir"
                            >
                                {character.inspiration ? '🌟 İLHAM' : '⭐ İLHAM'}
                            </button>
                        </div>
                    </div>

                    {/* Savaş durumu göstergesi */}
                    {combatState.isActive && (
                        <div className="combat-indicator">
                            <span className="combat-badge">⚔️ SAVAŞ</span>
                            <span className="round-badge">Tur {combatState.round}</span>
                        </div>
                    )}
                </div>
                <div className="menu-handle top-handle" onClick={() => setIsTopOpen(!isTopOpen)}>
                    {isTopOpen ? '▲' : '▼'}
                </div>
            </div>

            {/* ================= LAYER: SOL MENÜ (Stats & Skills) ================= */}
            <div className={`layer-sidebar left-sidebar ${isLeftOpen ? 'open' : 'closed'}`}>
                <div className="left-handle" onClick={() => setIsLeftOpen(!isLeftOpen)}>
                    {isLeftOpen ? '◀' : '▶'}
                </div>
                <div className="sidebar-content">
                    {/* 6 Stat Grid */}
                    <div className="pd-attributes-grid">
                        {Object.keys(statConfig).map(stat => {
                            const mod = calculateModifier(character.stats[stat]);
                            return (
                                <div
                                    key={stat}
                                    className={`pd-attr-btn ${selectedStat === stat ? 'selected' : ''}`}
                                    onClick={() => setSelectedStat(stat)}
                                >
                                    <div className="attr-layout">
                                        <span className="attr-name">{stat.substring(0, 3).toUpperCase()}</span>
                                        <span className="attr-val">{character.stats[stat]}</span>
                                        <span className="attr-mod">{mod >= 0 ? `+${mod}` : mod}</span>
                                    </div>
                                </div>
                            );
                        })}
                    </div>

                    {/* Seçili Stat Başlığı ve Roll */}
                    <div className="pd-skills-header">
                        <h2>{selectedStat}</h2>
                        <button
                            className="roll-stat-btn"
                            onClick={() => rollDice(`${selectedStat} Kontrolü`, calculateModifier(character.stats[selectedStat]))}
                        >
                            🎲 {selectedStat.toUpperCase()} AT
                        </button>
                    </div>

                    {/* Skills Listesi */}
                    <div className="pd-skills-list">
                        {statConfig[selectedStat].map(skill => {
                            const bonus = getSkillBonusValue(selectedStat, skill);
                            const isProficient = character.proficiencies && character.proficiencies[`${selectedStat}-${skill}`];
                            return (
                                <div
                                    key={skill}
                                    className={`pd-skill-row ${isProficient ? 'proficient' : ''}`}
                                    onClick={() => rollDice(skill, bonus)}
                                >
                                    <div className={`pd-prof-dot ${isProficient ? 'active' : ''}`}></div>
                                    <span className="pd-skill-name">{skill}</span>
                                    <span className="pd-skill-bonus">{bonus >= 0 ? `+${bonus}` : bonus}</span>
                                </div>
                            );
                        })}
                    </div>
                </div>
            </div>

            {/* ================= LAYER: SAĞ MENÜ (Dice Logs) ================= */}
            <div className={`layer-sidebar right-sidebar ${isRightOpen ? 'open' : 'closed'}`}>
                <div className="right-handle" onClick={() => setIsRightOpen(!isRightOpen)}>
                    {isRightOpen ? '▶' : '◀'}
                </div>
                <div className="sidebar-content">
                    <div className="pd-log-header">
                        <h3>🎲 ZAR & LOGLAR</h3>
                        <div className="game-code-badge">
                            KOD: <span>{gameCode}</span>
                        </div>
                    </div>

                    {/* Combat Sırası (Savaş varsa) */}
                    {combatState.isActive && tokens.length > 0 && (
                        <div className="combat-order-mini">
                            <div className="combat-order-title">⚔️ SAVAŞ SIRASI</div>
                            {tokens.map((t, idx) => (
                                <div
                                    key={t.id}
                                    className={`combat-order-row ${idx === combatState.currentTurnIndex ? 'active' : ''}`}
                                >
                                    <span>{idx === combatState.currentTurnIndex ? '▶ ' : ''}{t.name || 'Anonim'}</span>
                                    <span className="init-tag">{t.initiativeRoll || '?'}</span>
                                </div>
                            ))}
                        </div>
                    )}

                    {/* Log Ekranı */}
                    <div className="pd-log-container" ref={logContainerRef}>
                        {logs.map(log => (
                            <div key={log.id} className={`pd-log-entry ${getLogClass(log.type)}`}>
                                <span className="log-time">[{new Date(log.id).toLocaleTimeString([], { hour: '2-digit', minute: '2-digit' })}]</span>
                                <span className="log-text">{log.text}</span>
                            </div>
                        ))}
                    </div>
                </div>
            </div>

        </div>
    );
};

export default PlayerDashboard;
